\item Ta có $\int_{-1}^{3} f(x) d x+\int_{3}^{5} f(x) d x=\int_{-1}^{5} f(x) d x \Rightarrow \int_{3}^{5} f(x) d x=\int_{-1}^{5} f(x) d x-\int_{-1}^{3} f(x) d x=5-2=3$.
\end{itemize}

